head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > filterFocusMode]\nGridView 컴포넌트가 필터링/정렬 될때 Body 에 선택되어 있던 포커스의 처리 방식을 설정합니다.",
    "validation" : [
        "미설정(기본값) 시, 정렬 전에 선택된 Body Cell 의 포커스를 유지합니다.",
        "미설정(기본값) 시, 세로/가로 스크롤이 포커스된 Body Cell 이 표시되도록 이동하며 onscrollend 이벤트가 발생할 수 있습니다.",
        "infocus 설정 시, 정렬 전에 선택된 Body Cell 위치에 포커스를 유지합니다.",
        "infocus 설정 시, 선택된 데이터와 관계없이 동일 위치에 포커스가 유지되므로 스크롤 및 이벤트가 발생하지 않습니다.",
        "outfocus 설정 시, 정렬 시 선택된 포커스를 제거합니다.",
        "outfocus 설정 시, 세로 스크롤이 최상단으로 이동합니다.",
        "followfocus 설정 시, 정렬 전에 선택된 Body Cell 의 포커스를 유지합니다.",
        "followfocus 설정 시, 세로/가로 스크롤이 포커스된 Body Cell 이 표시되도록 이동하며 onscrollend 이벤트가 발생하지 않습니다.",
        "fixScrollX 설정 시, 정렬 전에 선택된 Body Cell 의 포커스를 유지합니다.",
        "fixScrollX 설정 시, 세로 스크롤만 포커스된 Body Cell 이 표시되도록 이동하며 onscrollend 이벤트가 발생할 수 있습니다.",
        "'' 값과 'followfocus' 값의 차이는 onscrollend 이벤트의 발생 유무에 있습니다.",
        "focusMode=none 이면 포커스 전체가 비활성화되므로 filterFocusMode 속성에 의한 포커스 처리도 동작하지 않습니다.",
    ]
}



// 전역 상태 : onscrollend 발생 플래그 (포커스는 사용자가 하단 우측 셀을 직접 클릭해 획득)
scwin.gVar = { scrollEndFired: false };



scwin.onpageload = function () {
    // 정적 select1 은 초기 selectedIndex 미적용 → 기본값('') 명시 설정
    con_filterFocusMode.setValue("");
    con_focusMode.setValue("");

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (con 값은 렌더 시 결정 → Target 재생성 버튼으로만 반영)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 상태 초기화
    scwin.gVar.scrollEndFired = false;

    // 조건 값 읽기 (옵션 자체값 select1 → getValue)
    let vMode = con_filterFocusMode.getValue();
    let vFocusMode = con_focusMode.getValue();

    // 현재 설정/검증 안내 라벨 (target 생성 전 가장 먼저 생성)
    let lbl = '';
    lbl += '[전제] 30행 x 6열 그리드(가로/세로 스크롤 발생). col1 헤더 정렬(오름차순 시 하단 데이터가 상단으로 이동) 가능.';
    lbl += '\n현재 filterFocusMode=' + (vMode === '' ? '(미설정=기본)' : vMode) + ' / focusMode=' + (vFocusMode === '' ? '(미설정=cell)' : vFocusMode);
    lbl += '\n[절차] (1) (가로·세로 스크롤 이동) 클릭 -> 세로/가로 스크롤을 하단/우측 끝으로 이동시켜 하단 우측 영역을 화면에 노출(+onscrollend 플래그 초기화).';
    lbl += '\n(2) 화면에 보이는 하단 우측 셀(28행, col6)을 직접 클릭해 포커스를 잡으세요(oncellclick 에 포커스 출력).';
    lbl += '\n(3) col1 헤더를 클릭하여 정렬. (4) (정렬 후 상태 확인) 클릭.';
    lbl += '\n[확인] 포커스 위치(유지/이동/제거), scrollTop/scrollLeft 이동, onscrollend 발생여부를 con 값별로 비교.';
    $c.gcm.createLabel('label="' + lbl + '"', '', 'label1');

    // dataList 직접 생성 (30행 x 6열, col1 은 정렬 시 순서가 크게 바뀌도록 역순 값 구성)
    let ns = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + ns + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    for (let cIdx = 1; cIdx <= 6; cIdx++) {
        strDl += '<w2:column id="col' + cIdx + '" name="col' + cIdx + '" dataType="text"></w2:column>';
    }
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    $p.data.create(strDl);
    let arrDl = $p.data.getAllDataCollection("object");
    scwin.dlt_bind = arrDl[arrDl.length - 1];

    let jsonData = [];
    for (let i = 0; i < 30; i++) {
        // col1 = 역순 zero-pad (row0=30 ... row29=01) → 오름차순 정렬 시 하단행이 상단으로 이동
        let key = String(30 - i);
        if (key.length < 2) key = '0' + key;
        jsonData.push({
            "col1": key,
            "col2": "col2_" + (i + 1),
            "col3": "col3_" + (i + 1),
            "col4": "col4_" + (i + 1),
            "col5": "col5_" + (i + 1),
            "col6": "col6_" + (i + 1)
        });
    }
    scwin.dlt_bind.setJSON(jsonData, false);

    // target 생성 : sortable=true, filterFocusMode/focusMode 는 con 값 적용(미설정 시 속성 생략)
    let attrMode = (vMode === '') ? '' : ' filterFocusMode="' + vMode + '"';
    let attrFocus = (vFocusMode === '') ? '' : ' focusMode="' + vFocusMode + '"';

    let grp_comp = $c.gcm.getTestGroup();
    let s = '';
    s += '<w2:gridView ' + ns + ' sortable="true" sortEvent="onclick" showSortableImage="true"' + attrMode + attrFocus + ' dataList="data:dlt_bind" checkAllType="false" id="" ev:onscrollend="scwin.target1_onscrollend" ev:oncellclick="scwin.target1_oncellclick" style="width:430px;height:200px;">';
    s += '<w2:caption style="" id="caption1" value="filterFocusMode 테스트 그리드"></w2:caption>';
    s += '<w2:header style="" id="header1">';
    s += '<w2:row style="" id="row1">';
    s += '<w2:column width="130" style="" inputType="text" id="column1" value="col1"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column2" value="col2"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column3" value="col3"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column4" value="col4"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column5" value="col5"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" id="column6" value="col6"></w2:column>';
    s += '</w2:row>';
    s += '</w2:header>';
    s += '<w2:gBody style="" id="gBody1">';
    s += '<w2:row style="" id="row2">';
    s += '<w2:column width="130" style="" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" dataType="text" id="col2" dataList="col2"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" dataType="text" id="col4" dataList="col4"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" dataType="text" id="col5" dataList="col5"></w2:column>';
    s += '<w2:column width="130" style="" inputType="text" dataType="text" id="col6" dataList="col6"></w2:column>';
    s += '</w2:row>';
    s += '</w2:gBody>';
    s += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", s, grp_comp);
}



// (2) 사용자가 (스크롤 이동으로 노출된) 하단 우측 Body Cell 을 직접 클릭 -> filterFocusMode 가 읽는 this.focusedCell 이 잡힘.
//     이 클릭이 정렬 직전의 마지막 동작이므로, 여기서 onscrollend 플래그를 초기화하여
//     이후 정렬로 인한 스크롤 이동의 onscrollend 발생 유무만 순수하게 관측한다.
scwin.target1_oncellclick = function (rowIndex, columnIndex, columnId) {
    scwin.gVar.scrollEndFired = false;
    wf_body_bottom.getObj("scwin").setReturnValue("=====셀 클릭(포커스 획득 + onscrollend 플래그 초기화)===== clicked rowIndex=" + rowIndex + ", columnIndex=" + columnIndex + ", columnId=" + columnId);
    wf_body_bottom.getObj("scwin").setReturnValue("현재 포커스 : rowIndex=" + target1.getFocusedRowIndex() + ", colIndex=" + target1.getFocusedColumnIndex());
}



// (1) 가로·세로 스크롤 이동 : 하단/우측 영역이 화면에 오도록 세로·가로 스크롤을 실제로 이동.
//     이 위치에서 보이는 하단 우측 셀을 사용자가 직접 클릭해 focusedCell 을 잡은 뒤 정렬하면,
//     filterFocusMode 가 그 포커스 셀을 보이도록 스크롤을 어떻게 이동/미이동하는지,
//     onscrollend 발생 유무를 관측할 수 있다. (onscrollend 플래그도 초기화)
scwin.btn_prepare_onclick = function () {
    scwin.gVar.scrollEndFired = false;

    // 세로·가로 스크롤을 하단/우측 끝으로 이동시켜 하단 우측 영역을 화면에 노출
    target1.setScrollTop(100000);
    target1.setScrollLeft(100000);

    wf_body_bottom.getObj("scwin").setReturnValue("=====스크롤 이동 완료 (하단/우측 노출 → 보이는 셀을 클릭해 포커스)=====");
    wf_body_bottom.getObj("scwin").setReturnValue("scrollTop=" + target1.getScrollTop() + ", scrollLeft=" + target1.getScrollLeft());
}



// (3) 정렬 후 상태 확인 : con 값별 filterFocusMode 동작 관측
scwin.btn_observe_onclick = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====정렬 후 상태=====");
    wf_body_bottom.getObj("scwin").setReturnValue("포커스 : rowIndex=" + target1.getFocusedRowIndex() + ", colIndex=" + target1.getFocusedColumnIndex() + " (rowIndex=-1 이면 포커스 제거)");
    wf_body_bottom.getObj("scwin").setReturnValue("scrollTop=" + target1.getScrollTop() + ", scrollLeft=" + target1.getScrollLeft());
    wf_body_bottom.getObj("scwin").setReturnValue("onscrollend 발생여부 : " + scwin.gVar.scrollEndFired);
}



// onscrollend : filterFocusMode 로 인한 스크롤 이동이 최하단에 닿으면 발생
scwin.target1_onscrollend = function () {
    scwin.gVar.scrollEndFired = true;
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onscrollend===== (스크롤 이동으로 발생)");
}
